```typescript
// user.entity.ts
import { Entity, PrimaryGeneratedColumn, Column, OneToOne } from 'typeorm';
import { CustomerProfile } from './customer-profile.entity';
import { DeliveryDriverProfile } from './delivery-driver-profile.entity';

@Entity('users')
export class User {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column({ unique: true })
  email: string;

  @Column()
  passwordHash: string;

  @OneToOne(() => CustomerProfile, (profile) => profile.user)
  customerProfile?: CustomerProfile;

  @OneToOne(() => DeliveryDriverProfile, (profile) => profile.user)
  driverProfile?: DeliveryDriverProfile;
}

// customer-profile.entity.ts
@Entity('customer_profiles')
export class CustomerProfile {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @OneToOne(() => User)
  @JoinColumn()
  user: User;

  @Column()
  firstName: string;

  @Column()
  lastName: string;

  @Column({ nullable: true })
  deliveryAddress: string;
}

// delivery-driver-profile.entity.ts
@Entity('delivery_driver_profiles')
export class DeliveryDriverProfile {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @OneToOne(() => User)
  @JoinColumn()
  user: User;

  @Column()
  firstName: string;

  @Column()
  lastName: string;

  @Column()
  vehicleType: string;

  @Column()
  licensePlate: string;

  @Column({ type: 'jsonb', nullable: true })
  deliveryZones: string[]; // Liste des zones de livraison
}
```
